INSERT INTO questions ("id", "quiz_id", "content", "options", "correct_option_id", "difficulty", "created_at") VALUES ('708697b5-1c5a-405b-ba7d-d8e981ae9b7f', '483e53d4-0747-41af-9f06-88d12f9bac75', 'Which command is used to install a specific version of a package using pip?', '[{"id":"A","text":"pip install package==1.2.3"},{"id":"B","text":"pip install package=1.2.3"},{"id":"C","text":"pip install package:1.2.3"},{"id":"D","text":"pip install package@1.2.3"}]'::jsonb, 'A', 'HARD', '2026-07-23T12:50:29.860Z') ON CONFLICT DO NOTHING;
